def ajustar_antes(apps, schema_editor):
    """Dados de teste da regra antiga: estorno apagava a baixa logicamente; a MarketUP apaga de fato. Origens com os números da MarketUP."""
    ContaReceber = apps.get_model("financeiro", "ContaReceber")
    ContaPagar = apps.get_model("financeiro", "ContaPagar")
    Recebimento = apps.get_model("financeiro", "Recebimento")
    Lancamento = apps.get_model("financeiro", "LancamentoCaixa")
    for r in Recebimento.objects.exclude(estornado_em=None):
        if r.lancamento_id:
            Lancamento.objects.filter(pk=r.lancamento_id).delete()
        r.delete()
    Lancamento.objects.filter(descricao__startswith="Estorno de recebimento").delete()
    ContaReceber.objects.filter(origem=0).update(origem=3)
    ContaPagar.objects.filter(origem=0).update(origem=2)
    ContaPagar.objects.filter(origem=20).update(origem=5)
    Lancamento.objects.filter(origem=0, credito=True).update(origem=3)
    Lancamento.objects.filter(origem=0, credito=False).update(origem=2)
    # Saldos recalculados sem as baixas estornadas.
    for conta in ContaReceber.objects.all():
        amortizado = sum((r.valor + r.desconto - r.juros for r in Recebimento.objects.filter(conta=conta)), 0)
        conta.saldo = max(conta.valor - amortizado, 0)
        conta.save(update_fields=["saldo"])


def ligar_depois(apps, schema_editor):
    """Movimento de caixa ligado ao título da baixa e à conta gerencial dele."""
    Recebimento = apps.get_model("financeiro", "Recebimento")
    Lancamento = apps.get_model("financeiro", "LancamentoCaixa")
    for r in Recebimento.objects.exclude(lancamento=None).select_related("conta"):
        Lancamento.objects.filter(pk=r.lancamento_id).update(conta_receber=r.conta_id, conta_gerencial=r.conta.conta_gerencial_id)


